7	import type { H3Event, HTTPEvent } from "../event.ts";
8	import type { CookieSerializeOptions } from "cookie-es";
9	import type { SealOptions } from "./internal/iron-crypto.ts";
10	import type { H3EventContext } from "../types/context.ts";
11	import { getEventContext } from "./event.ts";
